Let me recall the actual code from that era. Around v0.2 era (Feb 2020), the `auto_import.rs` was:

```rust
use hir::{db::HirDatabase, HasSource, InFile, ModuleDef, PathResolution, SourceAnalyzer};
use ra_syntax::{
    ast::{self, NameOwner},
    AstNode, SmolStr,
};
use ra_text_edit::TextEditBuilder;

use crate::{
    assist_ctx::{Assist, AssistCtx},
    AssistId, ImportsLocator,
};

// Assist: auto_import
//
// Adds a use statement for a given fully-qualified path.
//
// ```
// fn process(map: std::collections::<|>HashMap<String, String>) {}
// ```
// ->
// ```
// use std::collections::HashMap;
//
// fn process(map: HashMap<String, String>) {}
// ```
pub(crate) fn auto_import<L: ImportsLocator>(ctx: AssistCtx<impl HirDatabase>, locator: &L) -> Option<Assist> {
    let name_ref: ast::NameRef = ctx.find_node_at_offset()?;

    // We don't want to mess with use statements
    if name_ref.syntax().ancestors().find_map(ast::UseItem::cast).is_some() {
        return None;
    }

    let analyzer: SourceAnalyzer = ctx.source_analyzer(name_ref.syntax(), None);

    // First check to see if this name is already imported
    // or otherwise already resolvable
    let path = ast::Path::from_name_ref(name_ref.clone());
    if let Some(PathResolution::Def(def)) = analyzer.resolve_path(ctx.db(), &path) {
        match def {
            ModuleDef::Module(_) | ModuleDef::BuiltinType(_) => return None,
            _ => {}
        }
    }

    let import_target = ctx.covering_element().text();
    if import_target.is_empty() {
        return None;
    }

    let module = analyzer.module()?;

    let imports = find_imports(locator, import_target.to_string());
    // If multiple definitions were found, sort them alphabetically.
    let mut imports: Vec<_> = imports.iter().collect();
    imports.sort();

    // Limit the amount of suggestions to avoid overwhelming the user.
    let imports = imports.into_iter().take(10);

    let mut actions: Vec<_> = imports
        .into_iter()
        .filter_map(|def| {
            // FIXME: Add option to choose any of the use paths
            // https://github.com/rust-analyzer/rust-analyzer/issues/1560
            let use_path = module.find_use_path(ctx.db(), *def)?;
            if use_path.is_self() {
                None
            } else {
                Some((format!("{}", use_path), use_path))
            }
        })
        .collect();

    actions.sort_by(|(a, _), (b, _)| a.cmp(b));
    actions.dedup_by(|(a, _), (b, _)| a == b);
    let imports = actions.into_iter().take(10).collect::<Vec<_>>();

    return ctx.add_assist_group(
        AssistId("auto_import"),
        format!("Add use `{}`", &import_target),
        || {
            actions
                .iter()
                .map(|(path, _)| {
                    return {
                        let mut edit = TextEditBuilder::default();
                        import_text_edit(edit, ctx.module_at_cursor(), path);

                        let mut target = ActionBuilder::default();
                        target.replace(name_ref.text_range(), name_ref.text().to_string());
                        target.label(format!("Import {}", path));
                        target
                    };
                })
                .collect()
        },
    );

    fn find_imports(
        locator: &impl ImportsLocator,
        name: impl ToString + Copy,
    ) -> Vec<ModuleDef> {
        locator.find_imports(name).into_iter().collect()
    }
}
```

