    let imports = find_imports(locator, import_target.to_string());
    // Sort and limit suggestions.
    let imports: Vec<_> = imports.into_iter().take(10).collect();

    let mut actions: Vec<(String, ModPath)> = imports
        .into_iter()
        .filter_map(|def| {
            let use_path = module.find_use_path(ctx.db, def)?;
            if use_path.is_self() {
                None
