use hir::{db::HirDatabase, ModuleDef, SourceAnalyzer};
use ra_syntax::{ast, AstNode, SmolStr};

use crate::{
    assist_ctx::{ActionBuilder, Assist, AssistCtx},
    auto_import_text_edit, AssistId, ImportsLocator,
};

// Assist: auto_import
//
// Adds a use statement for the name at the cursor, if the name is not
// currently in scope.
//
// NOTE: this assist requires an `ImportsLocator` and is therefore run through
// `assists_with_imports_locator` rather than `assists`.
//
// ```
// fn process(map: HashMap<|><String, String>) {}
// ```
// ->
// ```
// use std::collections::HashMap;
//
// fn process(map: HashMap<String, String>) {}
// ```
pub(crate) fn auto_import(
    ctx: AssistCtx<impl HirDatabase>,
    locator: &impl ImportsLocator,
) -> Option<Assist> {
    let name_ref: ast::NameRef = ctx.find_node_at_offset()?;

    // We don't want to mess with use statements
    if name_ref.syntax().ancestors().find_map(ast::UseItem::cast).is_some() {
        return None;
    }

    let analyzer: SourceAnalyzer = ctx.source_analyzer(name_ref.syntax(), None);

    // First check to see if this name is already imported
    // or otherwise already resolvable
    let path = name_ref.syntax().ancestors().find_map(ast::Path::cast)?;
    if analyzer.resolve_path(ctx.db, &path).is_some() {
        return None;
    }

    let import_target = name_ref.text().to_string();
    if import_target.is_empty() {
        return None;
    }

    let module = analyzer.module()?;

    let actions: Vec<_> = locator
        .find_imports(&import_target)
        .into_iter()
        .take(10)
        .filter_map(|def| {
            // FIXME: Add option to choose any of the use paths.
            // https://github.com/rust-analyzer/rust-analyzer/issues/1560
            let use_path = module.find_use_path(ctx.db, def)?;
            if use_path.is_self() {
                None
            } else {
                Some((format!("{}", use_path), use_path))
            }
        })
        .collect();

    let mut actions = actions;
    actions.sort_by(|(a, _), (b, _)| a.cmp(b));
    actions.dedup_by(|(a, _), (b, _)| a == b);
    let actions = actions.into_iter().take(10).collect::<Vec<_>>();

    if actions.is_empty() {
        return None;
    }

    ctx.add_assist_group(
        AssistId("auto_import"),
        format!("Add use `{}`", &import_target),
        move || {
            actions
                .iter()
                .map(|(path, use_path)| {
                    let mut edit = ActionBuilder::default();
                    edit.label(format!("Import {}", path));
                    let segments: Vec<SmolStr> =
                        use_path.to_string().split("::").map(SmolStr::new).collect();
                    auto_import_text_edit(
                        name_ref.syntax(),
                        name_ref.syntax(),
                        &segments,
                        edit.text_edit_builder(),
                    );
                    edit
                })
                .collect()
        },
    )
}

