//! Implements `ra_assists::ImportsLocator` on top of the symbol index, so that
//! the `auto_import` assist can propose imports for unresolved names.

use hir::{db::HirDatabase, source_binder::ToDef, InFile, ModuleDef, SourceBinder};
use ra_syntax::{ast, match_ast, AstNode};

use crate::{db::RootDatabase, symbol_index, Query};

pub(crate) struct ImportsLocator<'a> {
    pub(crate) db: &'a RootDatabase,
}

impl ra_assists::ImportsLocator for ImportsLocator<'_> {
    fn find_imports(&self, name: impl ToString) -> Vec<ModuleDef> {
        let name = name.to_string();
        let mut symbols = Vec::new();

        // Search in the current workspace.
        let mut query = Query::new(name.clone());
        query.exact();
        symbols.extend(symbol_index::world_symbols(self.db, query));

        // And in the dependencies.
        let mut query = Query::new(name);
        query.exact();
        query.libs();
        symbols.extend(symbol_index::world_symbols(self.db, query));

        let mut sb = SourceBinder::new(self.db);
        symbols
            .into_iter()
            .filter_map(|symbol| {
                let node = symbol.ptr.to_node(&self.db.parse(symbol.file_id).tree().syntax());
                match_ast! {
                    match node {
                        ast::StructDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::EnumDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::UnionDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::TraitDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::TypeAliasDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::FnDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::ConstDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::StaticDef(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        ast::Module(it) => {
                            to_module_def(&mut sb, it, symbol.file_id)
                        }
                        _ => None,
                    }
                }
            })
            .collect()
    }
}

fn to_module_def<T>(sb: &mut SourceBinder<'_>, def: T, file_id: crate::FileId) -> Option<ModuleDef>
where
    T: ToDef,
    T::Def: Into<ModuleDef>,
{
    sb.to_def(InFile::new(file_id.into(), def)).map(Into::into)
}

