mod tests {
    use ra_syntax::TextRange;

    use crate::mock_analysis::analysis_and_position;

    #[test]
    fn test_auto_import_creates_use_statement() {
        let fixture = r#"
//- /lib.rs
mod foo;

fn main() {
    let map: HashMap<|>;
}

//- /foo.rs
pub struct HashMap;
"#;

        let (analysis, pos) = analysis_and_position(fixture);
        let frange = crate::FileRange {
            file_id: pos.file_id,
            range: TextRange::offset_len(pos.offset, 0.into()),
        };
        let assists = analysis.assists(frange).unwrap();
        let auto_import =
            assists.iter().find(|assist| assist.id.0 == "auto_import").expect("auto import assist");
        let change = match &auto_import.change_data {
            either::Either::Left(change) => change,
            either::Either::Right(changes) => &changes[0],
        };
        let text = analysis.file_text(pos.file_id).unwrap();
        let actual = change.source_file_edits[0].edit.apply(&text);

        test_utils::assert_eq_text!(
            "use foo::HashMap;\n\nmod foo;\n\nfn main() {\n    let map: HashMap;\n}",
            &actual,
        );
    }

    #[test]
    fn test_auto_import_not_applicable_when_resolvable() {
        let fixture = r#"
//- /lib.rs
mod foo;
use foo::HashMap;

fn main() {
    let map: HashMap<|>;
}

//- /foo.rs
pub struct HashMap;
"#;

        let (analysis, pos) = analysis_and_position(fixture);
        let frange = crate::FileRange {
            file_id: pos.file_id,
            range: TextRange::offset_len(pos.offset, 0.into()),
        };
        let assists = analysis.assists(frange).unwrap();
        assert!(assists.iter().all(|assist| assist.id.0 != "auto_import"));
    }
}

