fn highlight_token_tree(
    sb: &mut SourceBinder<RootDatabase>,
    source_analyzer: &hir::SourceAnalyzer,
    token: SyntaxToken,
    file_id: FileId,
) -> Vec<HighlightedRange> {
    let src = InFile::new(file_id.into(), token);
    let range = src.value.text_range();
    let token = descend_into_macros_with_analyzer(sb.db, file_id, src.value, source_analyzer);

    let tag = match highlight_token_in_expansion(sb, &token) {
        Some(tag) => tag,
        None => return Vec::new(),
    };
    vec![HighlightedRange { range, tag, binding_hash: None }]
}
```

