```rust
fn highlight_node(
    sb: &mut SourceBinder<RootDatabase>,
    node: &SyntaxNode,
    bindings_shadow_count: &mut FxHashMap<Name, u32>,
    res: &mut Vec<HighlightedRange>,
    file_id: FileId,
    calc_binding_hash: &impl Fn(FileId, &Name, u32) -> u64,
) {
    let mut binding_hash = None;
    let tag = match node.kind() {
        FN_DEF => {
            bindings_shadow_count.clear();
            return;
        }
        ATTR => tags::LITERAL_ATTRIBUTE,
        // Special-case field init shorthand
        NAME_REF if node.parent().and_then(ast::RecordField::cast).is_some() => tags::FIELD,
        NAME_REF if node.ancestors().any(|it| it.kind() == ATTR) => return,
        NAME_REF => {
            let name_ref = node.clone().and_then(ast::NameRef::cast).unwrap();
            let name_kind = classify_name_ref(sb, InFile::new(file_id.into(), &name_ref))
                .map(|d| d.kind);
            match name_kind {
                Some(name_kind) => {
                    if let Local(local) = &name_kind {
                        if let Some(name) = local.name(sb.db) {
                            let shadow_count =
                                bindings_shadow_count.entry(name.clone()).or_default();
                            binding_hash = Some(calc_binding_hash(file_id, &name, *shadow_count))
                        }
                    };

                    highlight_name(sb.db, name_kind)
                }
                _ => return,
            }
        }
        NAME => {
            let name = node.clone().and_then(ast::Name::cast).unwrap();
            let name_kind = classify_name(sb, InFile::new(file_id.into(), &name)).map(|d| d.kind);

            if let Some(Local(local)) = &name_kind {
                if let Some(name) = local.name(sb.db) {
                    let shadow_count = bindings_shadow_count.entry(name.clone()).or_default();
                    *shadow_count += 1;
                    binding_hash = Some(calc_binding_hash(file_id, &name, *shadow_count))
                }
            };

            match name_kind {
                Some(name_kind) => highlight_name(sb.db, name_kind),
                None => name.syntax().parent().map_or(tags::FUNCTION, |x| match x.kind() {
                    STRUCT_DEF | ENUM_DEF | TRAIT_DEF | TYPE_ALIAS_DEF => tags::TYPE,
                    TYPE_PARAM => tags::TYPE_PARAM,
                    RECORD_FIELD_DEF => tags::FIELD,
                    _ => tags::FUNCTION,
                }),
            }
        }
        _ => return,
    };
    res.push(HighlightedRange { range: node.text_range(), tag, binding_hash })
}

fn highlight_token(res: &mut Vec<HighlightedRange>, token: &SyntaxToken) {
    let tag = match token.kind() {
        COMMENT => tags::LITERAL_COMMENT,
        STRING | RAW_STRING | RAW_BYTE_STRING | BYTE_STRING => tags::LITERAL_STRING,
        ATTR => tags::LITERAL_ATTRIBUTE,
        INT_NUMBER | FLOAT_NUMBER => tags::LITERAL_NUMERIC,
        BYTE => tags::LITERAL_BYTE,
        CHAR => tags::LITERAL_CHAR,
        LIFETIME => tags::TYPE_LIFETIME,
        T![unsafe] => tags::KEYWORD_UNSAFE,
        k if is_control_keyword(k) => tags::KEYWORD_CONTROL,
        k if k.is_keyword() => tags::KEYWORD,
        _ => return,
    };
    res.push(HighlightedRange { range: token.text_range(), tag, binding_hash: None })
}
```

