pub(crate) fn highlight(db: &RootDatabase, file_id: FileId) -> Vec<HighlightedRange> {
    let _p = profile("highlight");
    let parse = db.parse(file_id);
    let root = parse.tree().syntax().clone();

    fn calc_binding_hash(file_id: FileId, name: &Name, shadow_count: u32) -> u64 {
        fn hash<T: std::hash::Hash + std::fmt::Debug>(x: T) -> u64 {
            use std::{collections::hash_map::DefaultHasher, hash::Hasher};

            let mut hasher = DefaultHasher::new();
            x.hash(&mut hasher);
            hasher.finish()
        }

        hash((file_id, name, shadow_count))
    }

    let mut sb = SourceBinder::new(db);

    // Visited nodes to handle highlighting priorities
    // FIXME: retain only ranges here
    let mut highlighted: FxHashSet<SyntaxElement> = FxHashSet::default();
    let mut bindings_shadow_count: FxHashMap<Name, u32> = FxHashMap::default();

    let mut res: Vec<HighlightedRange> = Vec::new();
    let mut in_macro_call: Option<(ast::MacroCall, hir::SourceAnalyzer)> = None;
    for event in root.preorder_with_tokens() {
        match event {
            WalkEvent::Leave(_) => (),
            WalkEvent::Enter(element) => {
                if highlighted.contains(&element) {
                    continue;
                }

                let in_macro_tree = match &in_macro_call {
                    Some((macro_call, _)) => macro_call
                        .token_tree()
                        .map(|tt| element.text_range().is_subrange(&tt.syntax().text_range()))
                        .unwrap_or(false),
                    None => false,
                };
                if in_macro_tree {
                    if let NodeOrToken::Token(token) = element {
                        let source_analyzer = &in_macro_call.as_ref().unwrap().1;
                        let hi = highlight_token_tree(sb, source_analyzer, token, file_id);
                        res.extend(hi);
                    }
                    continue;
                }
                let outside_macro = match &in_macro_call {
                    Some((macro_call, _)) => {
                        !element.text_range().is_subrange(&macro_call.syntax().text_range())
                    }
                    None => false,
                };
                if outside_macro {
                    in_macro_call = None;
                }

                match element {
                    NodeOrToken::Node(node) => {
                        if let Some(macro_call) = ast::MacroCall::cast(node) {
                            let hi = highlight_macro(&mut highlighted, &macro_call);
                            res.extend(hi);
                            if let Some(tt) = macro_call.token_tree() {
                                let src = InFile::new(
                                    file_id.into(),
                                    macro_call.syntax().parent().unwrap(),
                                );
                                let source_analyzer = sb.analyze(src.as_ref(), None);
                                in_macro_call = Some((macro_call, source_analyzer));
                            }
                        } else {
                            highlight_node(
                                &mut sb,
                                &node,
                                &mut bindings_shadow_count,
                                &mut res,
                                file_id,
                                &calc_binding_hash,
                            );
                        }
                    }
                    NodeOrToken::Token(token) => highlight_token(&token, &mut res),
                }
            }
        }
    }
    res
}

