+                            TYPE_PARAM => tags::TYPE_PARAM,
+                            RECORD_FIELD_DEF => tags::FIELD,
+                            _ => tags::FUNCTION,
+                        }),
+                    }
+                }
+                NAME_REF => {
+                    let name_ref = ast::NameRef::cast(parent).unwrap();
+                    match classify_name_ref(sb, token.with_value(&name_ref)).map(|d| d.kind) {
+                        Some(name_kind) => highlight_name(sb.db, name_kind),
+                        None => return None,
+                    }
+                }
